{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "It defines a classroom library as materials a teacher acquires and makes available to students in that teacher’s classes.",
      "rationale": "Conveys teacher acquisition and availability to assigned students, but omits the requirement that the materials be made available in the teacher’s classroom."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "It defines a school library collection to exclude classroom libraries and course curriculum materials",
      "rationale": "Conveys both exclusions, but not the affirmative definition covering materials made available to students by an LEA-operated school or public charter school."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "defines “materials” to include books, recordings, games, applications, and subscription content.",
      "rationale": "Conveys several covered formats, but omits other expressly covered categories, including periodicals, newspapers, manuscripts, prints, and documents, and the scope of subscription content in any form."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would also add references to classroom libraries in Tennessee Code Annotated § 49-6-3803(a), (f), and (g)",
      "rationale": "Identifies all three amended subsections and conveys their extension to classroom libraries; the precise insertion wording is unnecessary."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The bill would also add references to classroom libraries in Tennessee Code Annotated § 49-6-3803(a), (f), and (g), and delete subsection (b), whose text is not supplied.",
      "rationale": "Expressly identifies the deletion of § 49-6-3803(b)."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Local boards of education and public charter school governing bodies would have to adopt policies for classroom libraries as well as for developing and reviewing school library collections.",
      "rationale": "Conveys the responsible governing bodies, mandatory policy adoption, and both categories of libraries covered."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The policies would need procedures for teachers and eligible students’ parents or legal guardians to refer classroom library materials for review.",
      "rationale": "Conveys the referral procedure and participating groups, but omits their ability to review materials themselves and does not explain that parental eligibility depends on the student having access to the classroom library."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "They would also need to give those parents and guardians multiple opportunities during the school year to view classroom library books.",
      "rationale": "In context, conveys the required opportunities for the relevant students’ parents and guardians to view classroom library books multiple times throughout the school year."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "The policies would have to prohibit teachers from knowingly or intentionally using a classroom library to get around the school’s library collection policy, including by offering materials found inappropriate for students’ age and maturity or unsuitable for the school’s educational mission.",
      "rationale": "Conveys the prohibition, knowledge or intent requirement, and general examples, but omits which bodies must make the findings and the distinction between their authority over age-and-maturity findings and educational-mission findings."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "It would take effect upon becoming law.",
      "rationale": "Accurately states the effective-date provision."
    }
  ]
}
